#!/usr/bin/env bash
#
# ZorkSec - SOC L1 Learning Edition : self-extracting installer
# Author: Mohammad Muneeruddin (Muneer461 / Zork)
#
# Idempotent: safe to re-run. Creates /opt/zorksec, a Python venv, writes all
# application files, and installs the global `zorksec` command (plus a `tools`
# alias for backward compatibility).
#
set -euo pipefail

ZORKSEC_HOME="${ZORKSEC_HOME:-/opt/zorksec}"
BIN_LINK="/usr/local/bin/zorksec"
ALIAS_LINK="/usr/local/bin/tools"
PYTHON_MIN_MAJOR=3
PYTHON_MIN_MINOR=10

c_green="\033[1;32m"; c_yellow="\033[1;33m"; c_red="\033[1;31m"; c_cyan="\033[1;36m"; c_reset="\033[0m"
say()  { printf "%b[zorksec]%b %s\n" "$c_cyan" "$c_reset" "$1"; }
ok()   { printf "%b[ ok ]%b %s\n" "$c_green" "$c_reset" "$1"; }
warn() { printf "%b[warn]%b %s\n" "$c_yellow" "$c_reset" "$1"; }
die()  { printf "%b[fail]%b %s\n" "$c_red" "$c_reset" "$1"; exit 1; }

# --- root check ------------------------------------------------------------
if [ "$(id -u)" -ne 0 ]; then
  die "Please run with sudo:  sudo ./install.sh"
fi

# Resolve the real (non-root) user so clones land in their home, not /root.
REAL_USER="${SUDO_USER:-$(id -un)}"
say "Installing ZorkSec to ${ZORKSEC_HOME} (invoking user: ${REAL_USER})"

# --- OS / dependency setup -------------------------------------------------
if command -v apt-get >/dev/null 2>&1; then
  say "Installing base dependencies via apt..."
  apt-get update -y >/dev/null 2>&1 || warn "apt-get update failed (continuing)"
  apt-get install -y python3 python3-venv python3-pip git >/dev/null 2>&1 \
    || warn "Some base packages may already be present"
else
  warn "apt-get not found; ensure python3 (>=3.10), python3-venv, pip and git are installed."
fi

# --- python version check --------------------------------------------------
PYBIN="$(command -v python3 || true)"
[ -n "$PYBIN" ] || die "python3 not found."
PYV_MAJOR="$($PYBIN -c 'import sys;print(sys.version_info[0])')"
PYV_MINOR="$($PYBIN -c 'import sys;print(sys.version_info[1])')"
if [ "$PYV_MAJOR" -lt "$PYTHON_MIN_MAJOR" ] || { [ "$PYV_MAJOR" -eq "$PYTHON_MIN_MAJOR" ] && [ "$PYV_MINOR" -lt "$PYTHON_MIN_MINOR" ]; }; then
  die "Python ${PYTHON_MIN_MAJOR}.${PYTHON_MIN_MINOR}+ required (found ${PYV_MAJOR}.${PYV_MINOR})."
fi
ok "Python ${PYV_MAJOR}.${PYV_MINOR} detected"

# --- directory layout ------------------------------------------------------
mkdir -p "$ZORKSEC_HOME"
for d in core web tui plugins registry database reports logs config templates static; do
  mkdir -p "$ZORKSEC_HOME/$d"
done
ok "Directory layout ready"

# --- remove conflicting legacy installs ------------------------------------
# Older builds installed to ~/.zorksec (and used eventlet/port 5000). If left
# in place, a stale 'zorksec'/'tools' launcher can shadow this install. Remove
# them so /opt/zorksec is the single source of truth.
for legacy in "/root/.zorksec" "$(eval echo ~$REAL_USER)/.zorksec"; do
  if [ -n "$legacy" ] && [ -d "$legacy" ] && [ "$legacy" != "$ZORKSEC_HOME" ]; then
    rm -rf "$legacy" && warn "Removed legacy install at $legacy"
  fi
done
# Drop stale launchers in common user-local bin dirs.
for old in "$(eval echo ~$REAL_USER)/.local/bin/zorksec" "$(eval echo ~$REAL_USER)/.local/bin/tools"; do
  [ -e "$old" ] && rm -f "$old" && warn "Removed stale launcher $old"
done

# --- write embedded application files --------------------------------------
write_file() {
  # $1 = relative path, $2 = base64 payload
  local target="$ZORKSEC_HOME/$1"
  mkdir -p "$(dirname "$target")"
  printf '%s' "$2" | base64 -d > "$target"
}

say "Writing application files..."
write_file "zorksec/__init__.py" ""
write_file "zorksec/cli.py" ""
write_file "zorksec/config.py" ""
write_file "zorksec/db/__init__.py" "IiIiRGF0YWJhc2UgbGF5ZXI6IFNRTEFsY2hlbXkgbW9kZWxzIGFuZCBzZXNzaW9uIG1hbmFnZW1lbnQuIiIiCg=="
write_file "zorksec/db/models.py" ""
write_file "zorksec/db/session.py" ""
write_file "zorksec/detection/__init__.py" ""
write_file "zorksec/detection/attack.py" ""
write_file "zorksec/registry/__init__.py" "IiIiVG9vbCByZWdpc3RyeTogdGhlIGN1cmF0ZWQgY2F0YWxvZyBhbmQgaXRzIGRlZmluaXRpb25zLiIiIgo="
write_file "zorksec/registry/catalog.py" ""
write_file "zorksec/repositories/__init__.py" "IiIiUmVwb3NpdG9yeSBsYXllcjogZW5jYXBzdWxhdGVzIGFsbCBkYXRhYmFzZSBhY2Nlc3MgYmVoaW5kIHBsYWluIG1ldGhvZHMuIiIiCg=="
write_file "zorksec/repositories/audit_repository.py" ""
write_file "zorksec/repositories/base.py" ""
write_file "zorksec/repositories/feed_repository.py" ""
write_file "zorksec/repositories/history_repository.py" ""
write_file "zorksec/repositories/report_repository.py" ""
write_file "zorksec/repositories/tool_repository.py" ""
write_file "zorksec/repositories/user_repository.py" ""
write_file "zorksec/security/__init__.py" "IiIiU2VjdXJpdHkgcHJpbWl0aXZlczogbWFzdGVyLWtleSBtYW5hZ2VtZW50IGFuZCBzeW1tZXRyaWMgZW5jcnlwdGlvbi4iIiIK"
write_file "zorksec/security/crypto.py" ""
write_file "zorksec/services/__init__.py" "IiIiU2VydmljZSBsYXllcjogYnVzaW5lc3MgbG9naWMgY29tcG9zZWQgZnJvbSByZXBvc2l0b3JpZXMuIiIiCg=="
write_file "zorksec/services/ai_service.py" ""
write_file "zorksec/services/attack_service.py" ""
write_file "zorksec/services/auth_service.py" ""
write_file "zorksec/services/dependency_service.py" ""
write_file "zorksec/services/detection_service.py" ""
write_file "zorksec/services/dfir_service.py" ""
write_file "zorksec/services/diagnostic_service.py" ""
write_file "zorksec/services/discovery_service.py" ""
write_file "zorksec/services/executor_service.py" ""
write_file "zorksec/services/health_service.py" ""
write_file "zorksec/services/lab_service.py" ""
write_file "zorksec/services/metrics_service.py" ""
write_file "zorksec/services/registry_service.py" ""
write_file "zorksec/services/report_service.py" ""
write_file "zorksec/services/soc_utils_service.py" ""
write_file "zorksec/services/ti_service.py" ""
write_file "zorksec/services/usage_service.py" ""
write_file "zorksec/tui/__init__.py" "IiIiVGVybWluYWwgdXNlciBpbnRlcmZhY2UgKHRoZSBpbnRlcmFjdGl2ZSBgYHRvb2xzYGAgY29tbWFuZCkuIiIiCg=="
write_file "zorksec/tui/app.py" ""
write_file "zorksec/tui/banner.py" ""
write_file "zorksec/utils/__init__.py" "IiIiU2hhcmVkIHV0aWxpdGllcyAobG9nZ2luZywgaGVscGVycykuIiIiCg=="
write_file "zorksec/utils/logging.py" ""
write_file "zorksec/utils/system.py" ""
write_file "zorksec/web/__init__.py" "IiIiV2ViIGRhc2hib2FyZCBwYWNrYWdlIChGbGFzayArIEZsYXNrLVNvY2tldElPICsgeHRlcm0uanMpLiIiIgo="
write_file "zorksec/web/app.py" ""
write_file "zorksec/web/static/zorksec.css" ""
write_file "zorksec/web/templates/base.html" ""
write_file "zorksec/web/templates/change_password.html" ""
write_file "zorksec/web/templates/dashboard.html" ""
write_file "zorksec/web/templates/diagnostics.html" ""
write_file "zorksec/web/templates/forgot_password.html" ""
write_file "zorksec/web/templates/lab.html" ""
write_file "zorksec/web/templates/login.html" ""
write_file "zorksec/web/templates/security_question.html" ""
write_file "zorksec/web/templates/terminal.html" ""
write_file "zorksec/web/templates/usage.html" ""
write_file "zorksec/web/terminal.py" ""
write_file "requirements.txt" "IyBab3JrU2VjIHJ1bnRpbWUgZGVwZW5kZW5jaWVzClNRTEFsY2hlbXk+PTIuMCw8My4wCmJjcnlwdD49NC4wCmNyeXB0b2dyYXBoeT49NDIuMApyaWNoPj0xMy4wCkZsYXNrPj0zLjAKRmxhc2stU29ja2V0SU8+PTUuMwpnZXZlbnQ+PTI0LjAKZ2V2ZW50LXdlYnNvY2tldD49MC4xMApKaW5qYTI+PTMuMQpyZXF1ZXN0cz49Mi4zMQpkaXN0cm8+PTEuOQpwc3V0aWw+PTUuOQo="
write_file "pyproject.toml" ""

ok "Application files written"

# --- python virtual environment -------------------------------------------
VENV="$ZORKSEC_HOME/.venv"
if [ ! -d "$VENV" ]; then
  say "Creating virtual environment..."
  "$PYBIN" -m venv "$VENV"
fi
say "Installing Python dependencies (this can take a minute)..."
"$VENV/bin/pip" install --quiet --upgrade pip
if ! "$VENV/bin/pip" install --quiet -r "$ZORKSEC_HOME/requirements.txt"; then
  warn "Full dependency install failed; installing core set so the CLI still works."
  "$VENV/bin/pip" install --quiet sqlalchemy bcrypt cryptography rich || die "Core dependency install failed."
fi
ok "Dependencies installed"

# --- launcher + global symlink --------------------------------------------
LAUNCHER="$ZORKSEC_HOME/zorksec-launch.sh"
cat > "$LAUNCHER" <<'LAUNCHEOF'
#!/usr/bin/env bash
ZORKSEC_HOME="${ZORKSEC_HOME:-/opt/zorksec}"
exec "$ZORKSEC_HOME/.venv/bin/python" -m zorksec.cli "$@"
LAUNCHEOF
chmod +x "$LAUNCHER"
ln -sf "$LAUNCHER" "$BIN_LINK"
# Backward-compatible alias: 'tools' still works for existing users.
ln -sf "$LAUNCHER" "$ALIAS_LINK"
ok "Global command installed: zorksec -> $LAUNCHER (alias: tools)"

# --- ownership + initialise -------------------------------------------------
chown -R "$REAL_USER":"$REAL_USER" "$ZORKSEC_HOME" 2>/dev/null || true
say "Initialising database, catalog, and default user..."
( cd "$ZORKSEC_HOME" && PYTHONPATH="$ZORKSEC_HOME" "$VENV/bin/python" -m zorksec.cli init ) || warn "init reported an issue"

# Re-fix ownership of any root-created runtime files (db, logs, key).
chown -R "$REAL_USER":"$REAL_USER" "$ZORKSEC_HOME" 2>/dev/null || true

printf "\n"
ok "ZorkSec installation complete!"
printf "%b\n" "${c_green}Next steps:${c_reset}"
printf "  zorksec          # launch the interactive terminal UI\n"
printf "  zorksec --web    # launch the web dashboard (auto-opens your browser)\n"
printf "  zorksec doctor   # verify the environment\n"
printf "\n  Default login: zorksec / zorksec  (you must change it on first login)\n"
